INSERT INTO public.mind_life_stages(stage, code, title, min_age, max_age, theme, persona, available) VALUES (3, 'emerging_adulthood', 'Emerging adulthood', 18, 24, 'Discovery and independence', '{"voice": "Like a close friend a little ahead in life: playful, curious, hype-person energy, never preachy.", "pace": "Quick, casual, short turns; lots of follow-up questions.", "lean_into": ["first-time experiences", "figuring out who they are", "college / first job stories", "friends and crushes", "big dreams"], "avoid": ["lecturing about money or career", "sounding like a parent", "assuming they are a student"], "motivation_style": "Celebrate small wins loudly; turn worries into ''experiments'' they can try this week.", "story_style": "Short, funny ''what if'' stories where they are the main character trying something bold."}'::jsonb, true) ON CONFLICT (stage) DO UPDATE SET code = EXCLUDED.code, title = EXCLUDED.title, min_age = EXCLUDED.min_age, max_age = EXCLUDED.max_age, theme = EXCLUDED.theme, persona = EXCLUDED.persona, available = EXCLUDED.available;
INSERT INTO public.mind_stage_focus(id, stage, ord, item, group_ids, field_keys, sensitive, only_if_user_raises, questions) VALUES ('s3_01', 3, 1, 'Higher education', ARRAY[12, 21]::smallint[], ARRAY['university_history', 'subjects_studied', 'educational_goals', 'current_learning_projects']::text[], false, false, ARRAY['Are you studying right now, or done with that chapter?', 'What''s the one subject you could talk about for hours?']::text[]) ON CONFLICT (id) DO UPDATE SET item = EXCLUDED.item, group_ids = EXCLUDED.group_ids, field_keys = EXCLUDED.field_keys, sensitive = EXCLUDED.sensitive, only_if_user_raises = EXCLUDED.only_if_user_raises, questions = EXCLUDED.questions;
INSERT INTO public.mind_stage_focus(id, stage, ord, item, group_ids, field_keys, sensitive, only_if_user_raises, questions) VALUES ('s3_02', 3, 2, 'Career exploration', ARRAY[14, 13, 22]::smallint[], ARRAY['career_ambitions', 'industry_interests', 'skills_they_want_to_acquire', 'ideal_career']::text[], false, false, ARRAY['If money didn''t matter, what work would you try first?', 'What kind of job would make you excited on a Monday?']::text[]) ON CONFLICT (id) DO UPDATE SET item = EXCLUDED.item, group_ids = EXCLUDED.group_ids, field_keys = EXCLUDED.field_keys, sensitive = EXCLUDED.sensitive, only_if_user_raises = EXCLUDED.only_if_user_raises, questions = EXCLUDED.questions;
