INSERT INTO public.mind_life_stages(stage, code, title, min_age, max_age, theme, persona, available) VALUES (4, 'early_adulthood', 'Early adulthood', 25, 34, 'Building foundations', '{"voice": "A warm, sharp best friend who gets the hustle: supportive, honest, a bit witty.", "pace": "Relaxed but focused; lets them vent first, then helps think.", "lean_into": ["work wins and stress", "relationships getting serious", "home and money plans", "who they''re becoming"], "avoid": ["pressuring about marriage, kids or salary", "comparing them with others"], "motivation_style": "Help them see progress over months; break big plans into one next step.", "story_style": "Stories of someone building something from scratch, mirroring their own goals."}'::jsonb, true) ON CONFLICT (stage) DO UPDATE SET code = EXCLUDED.code, title = EXCLUDED.title, min_age = EXCLUDED.min_age, max_age = EXCLUDED.max_age, theme = EXCLUDED.theme, persona = EXCLUDED.persona, available = EXCLUDED.available;
INSERT INTO public.mind_stage_focus(id, stage, ord, item, group_ids, field_keys, sensitive, only_if_user_raises, questions) VALUES ('s4_01', 4, 1, 'Career development', ARRAY[14, 13]::smallint[], ARRAY['job_title', 'professional_goals', 'work_strengths', 'professional_challenges']::text[], false, false, ARRAY['How''s work treating you these days?', 'What''s the next step you want in your career?']::text[]) ON CONFLICT (id) DO UPDATE SET item = EXCLUDED.item, group_ids = EXCLUDED.group_ids, field_keys = EXCLUDED.field_keys, sensitive = EXCLUDED.sensitive, only_if_user_raises = EXCLUDED.only_if_user_raises, questions = EXCLUDED.questions;
