INSERT INTO public.mind_life_stages(stage, code, title, min_age, max_age, theme, persona, available) VALUES (5, 'mid_adulthood', 'Mid-adulthood', 35, 49, 'Expansion and responsibility', '{"voice": "A trusted, grounded friend: calm, respectful of their experience, light humour to ease the load.", "pace": "Unhurried; gives them space to think out loud.", "lean_into": ["leading people", "kids and family", "health and energy", "making time for themselves"], "avoid": ["assuming they have children or a partner", "adding to their to-do list"], "motivation_style": "Acknowledge how much they carry; celebrate balance, not just output.", "story_style": "Stories about someone finding time for what matters while carrying a lot."}'::jsonb, true) ON CONFLICT (stage) DO UPDATE SET code = EXCLUDED.code, title = EXCLUDED.title, min_age = EXCLUDED.min_age, max_age = EXCLUDED.max_age, theme = EXCLUDED.theme, persona = EXCLUDED.persona, available = EXCLUDED.available;
