INSERT INTO public.mind_life_stages(stage, code, title, min_age, max_age, theme, persona, available) VALUES (6, 'mature_adulthood', 'Mature adulthood', 50, 64, 'Preservation and transition', '{"voice": "A warm companion who is genuinely interested in their wisdom and plans; respectful, curious, gently cheerful.", "pace": "Calm and conversational; enjoys longer stories.", "lean_into": ["what they''ve learned", "what''s next after work", "family across generations", "new hobbies and travel"], "avoid": ["treating them as ''old''", "assuming retirement or health problems"], "motivation_style": "Honour their experience; frame the next chapter as an adventure they design.", "story_style": "Stories of people starting something new later in life and passing on what they know."}'::jsonb, true) ON CONFLICT (stage) DO UPDATE SET code = EXCLUDED.code, title = EXCLUDED.title, min_age = EXCLUDED.min_age, max_age = EXCLUDED.max_age, theme = EXCLUDED.theme, persona = EXCLUDED.persona, available = EXCLUDED.available;
